// ---------------------------------------------------------------------------
// Core Storage Entities & Schema Definitions
// ---------------------------------------------------------------------------
ENTITY files_metadata (Sharded PostgreSQL / Spanner) {
  [PK ] file_id                UUID
  [IDX] workspace_id           UUID
        file_path              VARCHAR(1024)
        latest_version         INT
        is_deleted             BOOLEAN
}

ENTITY file_versions (Sharded PostgreSQL / Spanner) {
  [PK ] version_id             UUID
  [FK ] file_id                UUID
  [IDX] version_number         INT
        total_size_bytes       BIGINT
        committed_at           TIMESTAMPTZ
}

ENTITY chunk_manifests (PostgreSQL + S3 Content-Addressed Blobs) {
  [PK ] version_id             UUID (Composite PK)
  [PK ] chunk_index            INT (Composite PK)
  [IDX] chunk_sha256           CHAR(64) -> s3://blobs/
        chunk_size_bytes       INT (~4MB)
}

// Relationships: files_metadata --(1 : N (version history))--> file_versions --(1 : N (ordered 4MB chunks))--> chunk_manifests
